example:
{{ $site := data "site.json" }}
&lt;title&gt;{{ $site.title }}&lt;/title&gt;

{{ range data "links.json" }}
  &lt;a href="{{ path .path }}"&gt;{{ .name }}&lt;/a&gt;
{{ end }}

{{ $posts := sort "Meta.date" "desc" (sources "RelPath" "blog/*") }}
{{ range paginate 10 $posts }}
  &lt;h2&gt;{{ .Meta.title }}&lt;/h2&gt;
{{ end }}
Page {{ .Source.CurrentPage }} of {{ .Source.TotalPages }}

{{ range pages .Source }}
  &lt;a href="{{.Path}}"{{ if .Active }} aria-current="page"{{ end }}&gt;{{ .Page }}&lt;/a&gt;
{{ end }}

{{/* src/team.html */}}
{{ range data "team.json" }}
  &lt;a href="{{ page "team/member.html" .slug }}"&gt;{{ .name }}&lt;/a&gt;
{{ end }}

{{/* src/team/member.html, rendered at /team/member/&lt;slug&gt; */}}
{{ $slug := .Path }}
{{ range data "team.json" }}{{ if eq .slug $slug }}
  &lt;h1&gt;{{ .name }}&lt;/h1&gt;
{{ end }}{{ end }}

{{ if contains "/blog/" .Source.Path }}
  &lt;a href="{{ path "/blog" }}"&gt;All posts&lt;/a&gt;
{{ end }}
